def make_block_9x9(br, bc, cols):
    """Build one 3x3 block for the 9x9 output"""
    block = []

    # Determine column order
    if br == 1:
        col_order = [2, 1, 0]  # middle blocks reverse column order
    else:
        col_order = [0, 1, 2]  # top/bottom blocks use original order

    # Determine reversal pattern:
    # br in {0,2}, bc == 1: all columns reversed
    # br == 1, bc == 1: columns 1 and 0 reversed (based on col_order position)
    # else: no reversal

    num_reversed = []  # which position in col_order gets reversal
    if br in [0, 2]:
        if bc == 1:
            num_reversed = [0, 1, 2]  # all positions reversed
        else:
            num_reversed = []  # none
    elif br == 1:
        if bc == 1:
            # cols at position 0 and 1 in col_order are reversed
            num_reversed = [0, 1]  # positions 0,1 reversed
        else:
            num_reversed = []  # none
    else:
        num_reversed = []

    # Build block
    for r in range(3):
        row = []
        for col_pos in range(3):
            # Which input column provides this output column?
            input_col = cols[col_order[col_pos]]

            # Is this position reversed?
            is_reversed = (col_pos in num_reversed)

            if is_reversed:
                # row r reversed means we pick from 2-r
                val = input_col[2-r]
            else:
                val = input_col[r]
            row.append(val)
        block.append(row)

    return block

